describe('Main Layout Horizontal Scrolling', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application's main layout
    });

    it('should not allow horizontal scrolling on the main layout', () => {
        cy.get('body').should('have.css', 'overflow-x', 'hidden');
    });

    it('should not allow horizontal scrolling when resizing the window', () => {
        cy.viewport(500, 800); // Set viewport to a mobile size
        cy.get('body').should('have.css', 'overflow-x', 'hidden');

        cy.viewport(1200, 800); // Set viewport to a larger size
        cy.get('body').should('have.css', 'overflow-x', 'hidden');
    });
});
